import React from 'react';
import { createRoot } from 'react-dom/client';
import { ValidationProvider } from './context/ValidationContext';
import DevClientApp from './DevClientApp';

// Add debugging message to confirm JavaScript is running
console.log('JavaScript loaded and running');
document.title = 'MCP Client - Debug Mode';

// Add visual confirmation that JS is running
const debugElement = document.createElement('div');
debugElement.style.position = 'fixed';
debugElement.style.bottom = '10px';
debugElement.style.right = '10px';
debugElement.style.backgroundColor = 'green';
debugElement.style.color = 'white';
debugElement.style.padding = '5px 10px';
debugElement.style.borderRadius = '4px';
debugElement.style.fontSize = '12px';
debugElement.style.zIndex = '9999';
debugElement.textContent = 'JS Running';
document.body.appendChild(debugElement);

// Get the root element
const container = document.getElementById('root');

if (!container) {
  // Create a fallback element if root is not found
  const fallbackElement = document.createElement('div');
  fallbackElement.id = 'root';
  document.body.appendChild(fallbackElement);
  console.error('Root element not found, created fallback');
}

const root = createRoot(container || document.getElementById('root'));

// Add error boundary
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    console.error('React Error Boundary caught an error:', error, errorInfo);
    this.setState({ error, errorInfo });

    // Display error directly in DOM as backup
    const errorElement = document.createElement('div');
    errorElement.style.padding = '20px';
    errorElement.style.color = 'red';
    errorElement.style.backgroundColor = '#ffeeee';
    errorElement.style.border = '1px solid red';
    errorElement.style.borderRadius = '4px';
    errorElement.style.margin = '20px';
    errorElement.innerHTML = `<h3>Something went wrong</h3><pre>${error?.toString()}</pre>`;
    document.body.appendChild(errorElement);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '20px', color: 'red', backgroundColor: '#ffeeee', border: '1px solid red', borderRadius: '4px', margin: '20px' }}>
          <h3>Something went wrong</h3>
          <p>{this.state.error?.toString()}</p>
          <pre>{this.state.errorInfo?.componentStack}</pre>
          <div style={{ marginTop: '20px' }}>
            <FallbackApp />
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

// App wrapper that provides fallback in case of error
const AppLoader = () => {
  const [useDevClient, setUseDevClient] = useState(true);
  const [error, setError] = useState(null);

  const toggleApp = () => {
    setUseDevClient(!useDevClient);
  };

  const handleError = (err) => {
    console.error('App Error:', err);
    setError(err);
    setUseDevClient(false);
  };

  return (
    <div>
      {error && (
        <div style={{ 
          padding: '10px', 
          backgroundColor: '#ffeeee', 
          color: 'red',
          border: '1px solid red',
          marginBottom: '10px'
        }}>
          <p>Error: {error.toString()}</p>
        </div>
      )}

      <button 
        onClick={toggleApp}
        style={{
          position: 'fixed',
          top: '10px',
          right: '10px',
          zIndex: 1000,
          padding: '5px 10px',
          backgroundColor: useDevClient ? 'orange' : 'green',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}
      >
        Switch to {useDevClient ? 'Fallback App' : 'Dev Client'}
      </button>

      {useDevClient ? (
        <ErrorBoundary>
          <ValidationProvider>
            <DevClientApp />
          </ValidationProvider>
        </ErrorBoundary>
      ) : (
        <FallbackApp />
      )}
    </div>
  );
};

// Render the application with fallback handling
try {
  root.render(
    <React.StrictMode>
      <ValidationProvider>
        <DevClientApp />
      </ValidationProvider>
    </React.StrictMode>
  );
  console.log('React rendering completed');
} catch (error) {
  console.error('Error during render:', error);
  // Display fallback content if React rendering completely fails
  document.body.innerHTML = `
    <div style="padding: 20px; text-align: center;">
      <h2>Failed to start MCP Client</h2>
      <p>Error: ${error?.message || 'Unknown error'}</p>
      <p>Check the console for more details.</p>
    </div>
  `;
}
